-- Kiểm thử báo cáo vận tải / bán vé: quyền, cấu trúc, cô lập nhà xe.
begin;
create extension if not exists pgtap with schema extensions;
select * from no_plan();
insert into auth.users (id, email) values
  ('00000000-0000-0000-0000-0000000000a1', 'p@test.local'), ('00000000-0000-0000-0000-0000000000b1', 'ua@test.local'),
  ('00000000-0000-0000-0000-0000000000b3', 'bv@test.local'), ('00000000-0000-0000-0000-0000000000c1', 'ub@test.local');
set local role authenticated;
set local request.jwt.claims = '{"sub":"00000000-0000-0000-0000-0000000000a1","role":"authenticated"}';
select lives_ok($$ select public.bootstrap_platform_admin() $$, 'Khởi tạo');
select lives_ok($$ select public.create_tenant('nha-xe-a', 'Nhà xe A') $$, 'Tạo nhà xe A');
select lives_ok($$ select public.create_tenant('nha-xe-b', 'Nhà xe B') $$, 'Tạo nhà xe B');
reset role;
select lives_ok($$ select public.svc_register_app_user('00000000-0000-0000-0000-0000000000b1', (select id from public.tenants where code = 'nha-xe-a'), '0900000001', 'Chủ A', 'owner') $$, 'Chủ A');
select lives_ok($$ select public.svc_register_app_user('00000000-0000-0000-0000-0000000000b3', (select id from public.tenants where code = 'nha-xe-a'), '0900000004', 'Bán vé A', 'seller') $$, 'Bán vé A');
select lives_ok($$ select public.svc_register_app_user('00000000-0000-0000-0000-0000000000c1', (select id from public.tenants where code = 'nha-xe-b'), '0900000003', 'Chủ B', 'owner') $$, 'Chủ B');

set local role authenticated;
set local request.jwt.claims = '{"sub":"00000000-0000-0000-0000-0000000000b1","role":"authenticated"}';
select lives_ok($$ insert into public.vehicle_types (code, name, reg_seats, reg_berths) values ('G16', 'Ghế 16', 16, 0) $$, 'Loại xe');
select lives_ok($$ insert into public.vehicles (plate, vehicle_type_id) values ('60F-004.39', (select id from public.vehicle_types)) $$, 'Xe');
select lives_ok($$ select public.save_fuel(null, jsonb_build_object('kind', 'ngoai', 'entry_date', '2026-10-04', 'vehicle_id', (select id from public.vehicles), 'liters', 40, 'unit_price', 22000)) $$, 'Đổ dầu');
select lives_ok($$ select public.import_vehicle_km(jsonb_build_array(jsonb_build_object('vehicle_id', (select id from public.vehicles), 'run_date', '2026-10-04', 'km', 250))) $$, 'Km GPS');
select is((public.report_transport('2026-10-01', '2026-10-31') -> 'vehicles' -> 0 ->> 'km_gps')::numeric, 250::numeric, 'Báo cáo vận tải: km GPS theo xe');
select is((public.report_transport('2026-10-01', '2026-10-31') -> 'vehicles' -> 0 ->> 'fuel_l')::numeric, 40::numeric, 'Báo cáo vận tải: lít dầu theo xe');
select is(jsonb_array_length(public.report_transport('2026-11-01', '2026-11-30') -> 'vehicles'), 0, 'Ngoài kỳ không có số liệu');
select is((public.report_sales('2026-10-01', '2026-10-31') -> 'total' ->> 'tickets')::int, 0, 'Báo cáo bán vé chạy được');
select throws_ok($$ select public.report_sales('2026-10-31', '2026-10-01') $$, '22023', null, 'Khoảng ngày sai bị chặn');
select ok(public.storage_usage() ? 'db_bytes' and (public.storage_usage() ->> 'db_bytes')::bigint > 0, 'Chủ xem được dung lượng');
-- Chữ ký có sẵn họ tên
select lives_ok($$ select public.set_signature_has_name('00000000-0000-0000-0000-0000000000b1', true) $$, 'Tự đặt chữ ký của mình đã có họ tên');
select lives_ok($$ select public.set_signature_has_name('giam_doc', true) $$, 'Chủ đặt cho chữ ký giám đốc');
select lives_ok($$ select public.save_staff(gen_random_uuid(), '{"full_name":"Lái xe X","joined_on":"2026-01-01","job_title":"Tổ trưởng lái xe"}') $$, 'Thêm lái xe');
select is((select job_title from public.staff_members where full_name = 'Lái xe X'), 'Tổ trưởng lái xe', 'Lưu chức vụ');
select lives_ok(format('select public.set_staff_job_title(%L, %L)', (select id from public.staff_members where full_name = 'Lái xe X'), 'Khác'), 'Điền chức vụ khi trống');
select is((select job_title from public.staff_members where full_name = 'Lái xe X'), 'Tổ trưởng lái xe', 'Đã có chức vụ thì không ghi đè');
select lives_ok(format('select public.set_signature_has_name(%L, true)', 'nv_' || (select id from public.staff_members limit 1)), 'Quản lý đặt cho chữ ký lái xe');
select ok(app.can_write_signature('nv_' || (select id from public.staff_members limit 1) || '.png'), 'Quản lý tải được chữ ký lái xe');
select ok(not app.can_write_signature('nv_00000000-0000-0000-0000-000000000099.png'), 'Không tải chữ ký cho nhân viên không thuộc nhà xe');
select is((select count(*)::int from public.signature_settings where has_name), 3, 'Đã lưu 3 cài đặt');
select ok(app.can_write_avatar((select id from public.staff_members where full_name = 'Lái xe X') || '.jpg'), 'Quản lý tải được ảnh đại diện lái xe');
select ok(not app.can_write_avatar('00000000-0000-0000-0000-000000000099.jpg'), 'Không tải ảnh đại diện cho người không thuộc nhà xe');
select ok(not app.can_write_avatar((select id from public.staff_members where full_name = 'Lái xe X') || '.png'), 'Chỉ nhận tên tệp .jpg chuẩn');
reset role;
set local role authenticated;
set local request.jwt.claims = '{"sub":"00000000-0000-0000-0000-0000000000b3","role":"authenticated"}';
select throws_ok($$ select public.report_transport('2026-10-01', '2026-10-31') $$, '42501', null, 'Bán vé không xem báo cáo');
select throws_ok($$ select public.report_sales('2026-10-01', '2026-10-31') $$, '42501', null, 'Bán vé không xem báo cáo bán vé');
select throws_ok($$ select public.storage_usage() $$, '42501', null, 'Bán vé không xem dung lượng');
select throws_ok($$ select public.set_signature_has_name('00000000-0000-0000-0000-0000000000b1', false) $$, '42501', null, 'Không đổi được chữ ký người khác');
select throws_ok($$ select public.set_signature_has_name('giam_doc', false) $$, '42501', null, 'Bán vé không đổi chữ ký giám đốc');
select is((select count(*)::int from public.signature_settings), 3, 'Cùng nhà xe đọc được cài đặt chữ ký');
select ok(not app.can_write_signature('nv_' || (select id from public.staff_members limit 1) || '.png'), 'Bán vé không tải chữ ký lái xe');
select ok(not app.can_write_avatar((select id from public.staff_members where full_name = 'Lái xe X') || '.jpg'), 'Bán vé không đổi ảnh đại diện người khác');
reset role;
set local role authenticated;
set local request.jwt.claims = '{"sub":"00000000-0000-0000-0000-0000000000c1","role":"authenticated"}';
select is(jsonb_array_length(public.report_transport('2026-10-01', '2026-10-31') -> 'vehicles'), 0, 'Nhà xe B không thấy số liệu của A');
select is((select count(*)::int from public.signature_settings), 0, 'Nhà xe B không thấy cài đặt chữ ký của A');
select ok(not app.can_write_avatar((select id::text from public.staff_members where full_name = 'Lái xe X') || '.jpg'), 'Nhà xe B không ghi ảnh đại diện của A');
reset role;
select * from finish();
rollback;
